function salesVelocity(rows,windows=[7,30,60,90]){const dates=[...new Set((rows||[]).map(r=>String(r.date||'').slice(0,10)).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)))].sort(),end=dates.at(-1);if(!end)return windows.map(days=>({days,end:null,start:null,observedDays:0,units:0,orders:0,unitsPerDay:null,ordersPerDay:null}));const endMs=Date.parse(`${end}T00:00:00Z`);return windows.map(days=>{const start=new Date(endMs-(days-1)*86400000).toISOString().slice(0,10),slice=(rows||[]).filter(r=>{const d=String(r.date||'').slice(0,10);return d>=start&&d<=end}),observedDays=new Set(slice.map(r=>String(r.date||'').slice(0,10))).size,units=slice.reduce((sum,r)=>sum+(+r.units||0),0),orders=slice.reduce((sum,r)=>sum+(+r.orders||0),0);return{days,start,end,observedDays,units,orders,unitsPerDay:observedDays?units/observedDays:null,ordersPerDay:observedDays?orders/observedDays:null}})}
function productSalesVelocity(rows,days=30){const overall=salesVelocity(rows,[days])[0];if(!overall.end)return[];const byProduct=new Map();for(const r of(rows||[])){const date=String(r.date||'').slice(0,10),product=String(r.product||'').trim();if(!product||date<overall.start||date>overall.end)continue;const item=byProduct.get(product)||{product,units:0,orders:0,dates:new Set()};item.units+=+r.units||0;item.orders+=+r.orders||0;item.dates.add(date);byProduct.set(product,item)}return[...byProduct.values()].map(r=>({product:r.product,units:r.units,orders:r.orders,observedDays:r.dates.size,unitsPerDay:r.dates.size?r.units/r.dates.size:null,ordersPerDay:r.dates.size?r.orders/r.dates.size:null,start:overall.start,end:overall.end})).sort((a,b)=>(b.unitsPerDay||0)-(a.unitsPerDay||0))}
function replenishmentPlan({available,inbound=0,reserved=0,dailySales,leadTimeDays,safetyDays=0}){const sellable=Math.max(0,(+available||0)+(+inbound||0)-(+reserved||0)),daily=+dailySales,lead=+leadTimeDays,safety=+safetyDays;if(!(daily>0))return{available:false,reason:'Daily sales evidence is required.'};if(!(lead>=0))return{available:false,reason:'Lead time is required.'};if(!(safety>=0))return{available:false,reason:'Safety-stock days must be zero or greater.'};const target=daily*(lead+safety),daysUntilReorder=Math.max(0,sellable/daily-lead-safety);return{available:true,sellable,target,daysUntilReorder,recommendedQuantity:Math.max(0,target-sellable)}}
function inventoryPriority(rows){const order={Critical:1,Low:2,Damaged:3,Healthy:4,'No sales evidence':5};return[...rows].map(row=>({...row,priority:row.risk==='Critical'?'Review stockout risk first':row.risk==='Low'?'Review replenishment timing':row.risk==='Damaged'?'Review damaged inventory':row.risk==='No sales evidence'?'Import sales evidence':'No immediate evidence-led action'})).sort((a,b)=>(order[a.risk]||99)-(order[b.risk]||99)||(a.daysCover??Infinity)-(b.daysCover??Infinity))}
