function phraseCoverage(text,keyword){const textTokens=normalizedTokens(text),keywordTokens=normalizedTokens(keyword),phrase=keywordTokens.join(' '),hay=textTokens.join(' ');return{phrase:!!phrase&&` ${hay} `.includes(` ${phrase} `),roots:[...new Set(keywordTokens.filter(token=>textTokens.includes(token)))]}}
