function render(page){const meta=PAGE_META[page],content=$('#content');if(!meta||!content)return false;$$('#sidebar-nav .nav-item').forEach(x=>x.classList.toggle('active',x.dataset.growthPage===page));$('#page-eyebrow').textContent=meta[0];$('#page-title').textContent=meta[1];$('#page-subtitle').textContent=meta[2];$('#breadcrumb').textContent=`${meta[0]} / ${meta[1]}`;content.innerHTML=`<div class="notice-banner"><b>CSV-first workspace.</b> Amazon API remains disabled; all metrics below come from imported or already-loaded data.</div>${pageSourceChips(page)}<div class="top-gap">${RENDERERS[page]()}${operationsPanel(page)}${page==='inventory-risk'?inventoryCapitalPanel():''}${page==='product-360'?profitScenarioPanel():''}${page==='listing-optimizer'?listingValidationPanel():''}</div>`;bind(content);root.KeywordOSI18N?.apply(document);history.replaceState(null,'',`#page=${encodeURIComponent(page)}`);return true}
