function downloadTemplate(kind){const csv=TEMPLATES[kind];if(!csv)return;const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`KeywordOS_${kind}_template.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),0)}
