function injectNav(){const nav=$('#sidebar-nav');if(!nav||$('#growth-nav'))return;const section=document.createElement('div');section.className='nav-section';section.id='growth-nav';section.innerHTML=`<div class="nav-section-title">GROWTH</div>${[['product-master','▣','Product Master'],['keyword-workflow','◎','Keyword Workflow'],['product-360','◉','Product 360'],['search-funnel','⌁','Search Funnel'],['asin-comparison','⇄','ASIN Compare'],['rank-intelligence','↗','Rank & Index'],['listing-optimizer','✎','Listing Optimizer'],['inventory-risk','▦','Inventory'],['action-outcomes','◎','Action Outcomes'],['competitor-snapshots','◌','Competitors'],['review-evidence','☷','Reviews'],['anomaly-center','⚠','Anomaly Center']].map(x=>`<button class="nav-item" data-page="${x[0]}" data-growth-page="${x[0]}" aria-label="${x[2]}"><span class="nav-icon">${x[1]}</span><span class="nav-label">${x[2]}</span></button>`).join('')}`;nav.appendChild(section);$$('[data-growth-page]',section).forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();render(b.dataset.growthPage)}))}
